
    .share-wrapper {
      display: flex;
      justify-content: center;
      flex-direction: column;
      align-items: center;
      color: #ffffff;
      width: 90%;
      margin: 0 auto;
      gap: 20px;
      .sharing-container {
        flex-direction: column;
        box-shadow: 0px 0px 20px 1px #10101c;
        width: 100%;
        margin: 10px auto;
        display: flex;
        justify-content: center;
        border-radius: 20px;
        overflow: hidden;
        flex: 2;

        .qr-container {
          background: #ffffff;
          padding: 30px;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          img {
            width: 120px;
            margin: 0 auto;
          }
        }
        .right-container {
          background: #212534;
          width: 100%;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          color: #ffffff;
          .share-content {
            padding: 10px 30px;
          }
          .share-link-wrapper {
            padding: 10px 30px;
            position: relative;
            display: flex;
            justify-content: space-between;
            align-items: center;
            width: 100%;
            gap: 20px;
            input {
              width: 100%;
              border: none;
              background-color: #2b2b4b;
              padding: 10px;
            }
          }
        }
      }
      .otherlinks {
        display: flex;
        gap: 10px;
        flex-direction: column;
        .links {
          display: flex;
          justify-content: center;
          align-items: center;
          gap: 20px;
          svg {
            width: 30px;
            fill: #ffffff;
          }
        }
        .note {
          font-size: 12px;
        }
      }
    }
    .preferred {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 10px;
      margin-bottom: 10px;
    }
